private static function isTableName(string $tableName, ?Worksheet $worksheet): bool
{
    if ($worksheet === null || $worksheet->getParent() === null) {
        return false;
    }

    $lookupName = Shared\StringHelper::strToUpper($tableName);
    foreach ($worksheet->getParent()->getAllSheets() as $worksheet) {
        foreach ($worksheet->getTableCollection() as $table) {
            if (Shared\StringHelper::strToUpper($table->getName()) === $lookupName) {
                return true;
            }
        }
    }

    return false;
}

